import type { ByProjectKeyRequestBuilder } from '@commercetools/platform-sdk/dist/declarations/src/generated/client/by-project-key-request-builder';
import type { ProductType } from '@commercetools/platform-sdk';
import { EvaluationContext } from './types';

/**
 * What the engine needs to know about the Project before it can judge a
 * product: the Product Type keys a rule may name, and the currencies a price
 * condition is written in. Loaded once per run and handed to every
 * evaluation, so a sweep of the catalog costs one pair of reads.
 */

const PAGE_SIZE = 100;

/** Currencies with a minor unit that is not two digits. */
const FRACTION_DIGITS: Record<string, number> = {
  BHD: 3,
  CLP: 0,
  ISK: 0,
  JOD: 3,
  JPY: 0,
  KRW: 0,
  KWD: 3,
  OMR: 3,
  TND: 3,
  VND: 0,
};

export async function loadProductTypes(
  apiRoot: ByProjectKeyRequestBuilder
): Promise<ProductType[]> {
  const productTypes: ProductType[] = [];
  let lastId: string | undefined;

  for (;;) {
    const { body } = await apiRoot
      .productTypes()
      .get({
        queryArgs: {
          limit: PAGE_SIZE,
          sort: ['id asc'],
          withTotal: false,
          ...(lastId ? { where: `id > "${lastId}"` } : {}),
        },
      })
      .execute();

    if (body.results.length === 0) break;
    productTypes.push(...body.results);
    lastId = body.results[body.results.length - 1].id;
    if (body.results.length < PAGE_SIZE) break;
  }

  return productTypes;
}

/**
 * The Project's currencies, if this client may read them.
 *
 * Reading the Project needs `view_project_settings`, which a connector
 * that only categorizes products has no other use for. Without it, price
 * conditions fall back to two fraction digits and comparisons still work
 * — which is a far better outcome than every rule silently not firing
 * because one optional read was refused.
 */
async function loadCurrencies(
  apiRoot: ByProjectKeyRequestBuilder
): Promise<string[]> {
  try {
    const { body } = await apiRoot.get().execute();
    return body.currencies ?? [];
  } catch {
    return [];
  }
}

export async function loadEvaluationContext(
  apiRoot: ByProjectKeyRequestBuilder,
  now: Date = new Date()
): Promise<{ ctx: EvaluationContext; productTypes: ProductType[] }> {
  const [productTypes, currencies] = await Promise.all([
    loadProductTypes(apiRoot),
    loadCurrencies(apiRoot),
  ]);

  const defaultCurrency = currencies[0];
  const fractionDigitsByCurrency = Object.fromEntries(
    currencies.map((currency) => [currency, FRACTION_DIGITS[currency] ?? 2])
  );

  return {
    productTypes,
    ctx: {
      now,
      productTypeKeyById: Object.fromEntries(
        productTypes
          .filter((productType) => Boolean(productType.key))
          .map((productType) => [productType.id, productType.key as string])
      ),
      defaultCurrency,
      fractionDigitsByCurrency,
    },
  };
}
